import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { Card, Button, Form, ListGroup, Alert } from 'react-bootstrap';
import { AuthContext } from '../context/AuthContext';

export default function Feed() {
  const [posts, setPosts] = useState([]);
  const [commentText, setCommentText] = useState('');
  const [error, setError] = useState('');
  const { token, username } = useContext(AuthContext);

  const fetchPosts = () => {
    axios.get('http://localhost:5000/posts')
      .then(res => setPosts(res.data))
      .catch(() => setError('Failed to load posts'));
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  const likePost = (postId) => {
    axios.patch(`http://localhost:5000/posts/${postId}/like`, {}, {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(res => {
        setPosts(posts.map(p => p._id === postId ? res.data : p));
      })
      .catch(() => setError('Failed to like post'));
  };

  const addComment = (postId) => {
    if (!commentText.trim()) return;
    axios.post(`http://localhost:5000/posts/${postId}/comment`, { comment: commentText }, {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(res => {
        setPosts(posts.map(p => p._id === postId ? res.data : p));
        setCommentText('');
      })
      .catch(() => setError('Failed to add comment'));
  };

  return (
    <>
      <h2>Feed</h2>
      {error && <Alert variant="danger">{error}</Alert>}
      {posts.length === 0 && <p>No posts yet.</p>}
      {posts.map(post => {
        const liked = post.likes.includes(username);
        return (
          <Card key={post._id} className="mb-3">
            <Card.Body>
              <Card.Title>{post.username}</Card.Title>
              <Card.Text>{post.text}</Card.Text>
              {post.imageUrl && <Card.Img variant="bottom" src={`http://localhost:5000${post.imageUrl}`} />}
              <div className="mt-2">
                <Button variant={liked ? 'primary' : 'outline-primary'} onClick={() => likePost(post._id)}>
                  {liked ? 'Unlike' : 'Like'} ({post.likes.length})
                </Button>
              </div>
            </Card.Body>
            <ListGroup variant="flush">
              {post.comments.map((c, i) => (
                <ListGroup.Item key={i}>
                  <strong>{c.username}</strong>: {c.comment}
                </ListGroup.Item>
              ))}
              <ListGroup.Item>
                <Form onSubmit={(e) => { e.preventDefault(); addComment(post._id); }}>
                  <Form.Control
                    type="text"
                    placeholder="Add a comment..."
                    value={commentText}
                    onChange={e => setCommentText(e.target.value)}
                  />
                </Form>
              </ListGroup.Item>
            </ListGroup>
          </Card>
        );
      })}
    </>
  );
}
